import{_ as r,c as i,o as l,ah as o}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/あとがき/0_context_summary.md","filePath":"scripts/output/あとがき/0_context_summary.md"}'),s={name:"scripts/output/あとがき/0_context_summary.md"};function a(n,t,e,_,c,g){return l(),i("div",null,[...t[0]||(t[0]=[o('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇为全书后记。SKY-HI回顾本作较前作更集中讨论日本音乐与演艺行业的原因，指出行业停滞与结构性问题正逐渐受到社会关注，而BMSG也成为推动变化的契机。他结合自身二十余年的经历，表达改变行业、帮助艺人摆脱不公处境的强烈使命感，并强调改革不仅关乎BMSG，也关乎整个行业的从业者。结尾号召读者共同参与这场“音乐行业的小革命”，以善意、平等、努力和相互支持，享受音乐与人生。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物／术语／语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物／术语／语气风险点&quot;">​</a></h2><ul><li><strong>SKY-HI／日高光启</strong>：作者署名为SKY-HI，正文使用第一人称“俺”，应保持其个人口吻。</li><li><strong>BMSG</strong>：统一保留官方英文大写，不宜译为泛称。</li><li><strong>芸能界</strong>：根据语境译为“演艺圈”或“娱乐行业”，避免误译为单纯的“艺能界”。</li><li><strong>アーティスト／アイドル</strong>：分别译为“艺人／艺术家”和“偶像”，需结合行业语境区分。</li><li><strong>泥水をすすり続けてきた</strong>：比喻长期忍受困苦，不宜直译得过于生硬。</li><li><strong>同胞</strong>：指共同走过行业道路的同行、伙伴，不一定是血缘意义上的同胞。</li><li><strong>あの頃の俺予備軍</strong>：核心比喻，指“可能重蹈当年自己困境的人”，需保留自嘲与保护意味。</li><li><strong>ビバ苦汁！にげー！うめー！</strong>：带有夸张、玩笑和自我激励色彩，不能处理得过度书面化。</li><li><strong>命賭けて勝負する</strong>：强调决心，宜译为“拼上性命去挑战／奋力一搏”，注意避免渲染实际危险。</li><li><strong>革命</strong>：是推动行业改革的象征性表达，不宜译成政治化或暴力化的“革命”语境。</li><li><strong>小学阶段的训诫语</strong>：“只顾自己好是卑鄙的”“开朗、友爱、健康最重要”等应保留朴素、直白的儿童教育感。</li><li>全文在严肃的行业批评、个人创伤、热血号召与轻松玩笑之间切换，语气不可统一压平。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>采用<strong>真诚、热烈、略带口语感</strong>的第一人称表达，避免翻译成演讲稿或企业宣言。</li><li>保留作者的幽默、自嘲和情绪起伏，尤其是括号中的“笑”、感叹句及短句节奏。</li><li>“自分”“俺”等人称不必逐字对应，但应根据段落分别体现克制、亲近、激昂和脆弱。</li><li>“我们”“你也属于这场革命”等句子要保留对读者的直接邀请感。</li><li>对行业批评应准确、克制，不额外强化为对整个日本行业的绝对否定。</li><li>结尾应维持逐步升温的节奏：感谢相关人士—宣告变化已经发生—号召尽情享受音乐与人生。</li><li>“応援してます！俺たちのことも応援してね。応援しあおう。”建议译得简短自然，体现双向支持，而非单方面请求粉丝应援。</li></ul>',6)])])}const m=r(s,[["render",a]]);export{d as __pageData,m as default};
